<script setup lang="ts">
import { onMounted, ref } from 'vue'; import type { UsageSummary } from '@cyberboard/types'; import StatePanel from '@cyberboard/ui/components/StatePanel.vue'; import { getApiErrorMessage, portalApi } from '../api'
const loading=ref(true); const error=ref(''); const usage=ref<UsageSummary|null>(null); const format=(bytes:number)=>`${(bytes/1e9).toFixed(1)} GB`; const maxBar=()=>Math.max(...(usage.value?.daily.map((item)=>item.bytes)??[1]),1)
async function load(){loading.value=true;error.value='';try{usage.value=await portalApi.getUsage()}catch(cause){usage.value=null;error.value=getApiErrorMessage(cause)}finally{loading.value=false}}; onMounted(load)
</script>
<template><div class="portal-heading"><div><p class="eyebrow">额度与统计</p><h1>使用量</h1><p>按服务端返回的时间桶查看流量消耗和额度预测。</p></div><button class="button button--secondary" type="button" :disabled="loading" @click="load">{{loading?'加载中…':'刷新'}}</button></div><StatePanel v-if="loading" title="正在加载用量" description="正在读取用量汇总和时间桶。"/><StatePanel v-else-if="error" title="用量加载失败" :description="error" action-label="重试" @action="load"/><StatePanel v-else-if="!usage" title="暂无用量数据" description="服务端尚未返回当前用户的用量。"/><template v-else><section class="portal-metrics"><article><span>本周期使用</span><strong>{{format(usage.usedBytes)}}</strong><small>额度 {{format(usage.quotaBytes)}}</small></article><article><span>今日使用</span><strong>{{format(usage.todayBytes)}}</strong><small>服务端统计</small></article><article><span>预计周期使用</span><strong>{{format(usage.projectedBytes)}}</strong><small>服务端预测</small></article></section><section class="portal-panel chart-placeholder"><div class="chart-header"><h2>每日用量</h2><span class="muted">{{usage.periodStart}} 至 {{usage.periodEnd}}</span></div><StatePanel v-if="!usage.daily.length" title="暂无每日用量" description="服务端尚未返回时间桶。"/><div v-else class="bars"><i v-for="item in usage.daily" :key="item.date" :title="`${item.date}: ${format(item.bytes)}`" :style="{height:`${Math.max(5,item.bytes/maxBar()*100)}%`}"/></div></section></template></template>
